"""Local campaign/operator interface. It never sends mail or controls instruments."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from .measurements import (
    density_archimedes,
    microscopy_observations,
    microscopy_specimen_observations,
    read_sps_csv,
    review_reduction,
)
from .operator import Campaign
from .scientific_checks import evaluate_campaign_request


def read_json(path):
    with Path(path).open(encoding="utf-8") as handle:
        return json.load(handle)


def parser():
    root = argparse.ArgumentParser(description=__doc__)
    sub = root.add_subparsers(dest="command", required=True)
    init = sub.add_parser("init", help="Create external persistent state; no physical activation")
    init.add_argument("--state", required=True)
    init.add_argument("--mode", choices=("synthetic", "physical"), required=True)
    init.add_argument("--campaign-id", required=True)
    init.add_argument("--config", help="Optional immutable resource/metadata JSON")
    simulation = sub.add_parser(
        "init-simulation", help="Initialize attributed source prior; no experiment or inference"
    )
    simulation.add_argument("--state", required=True)
    simulation.add_argument("--run-dir", required=True)
    simulation.add_argument("--campaign-id", required=True)
    simulation.add_argument("--max-specimens", type=int, default=36)
    simulation.add_argument("--microstructure", action="store_true",
                            help="Use the versioned distribution-aware conditional lab context")
    fulfill = sub.add_parser(
        "fulfill-simulation", help="Native synthetic execution and private import; no release"
    )
    for flag in ("state", "request-id", "runtime", "artifacts", "world-config"):
        fulfill.add_argument("--" + flag, required=True)
    fulfill.add_argument("--seed", type=int, required=True)
    for name in ("status", "verify", "evidence", "artifacts"):
        command = sub.add_parser(name)
        command.add_argument("--state", required=True)
    adopt = sub.add_parser("adopt", help="Stage and verify executable model twice in Docker")
    adopt.add_argument("--state", required=True)
    adopt.add_argument("--source", required=True)
    adopt.add_argument("--test-request", required=True)
    adopt.add_argument("--rationale", required=True)
    adopt.add_argument("--call-id", required=True)
    submit = sub.add_parser(
        "submit", help="Freeze active executable predictions and request review"
    )
    submit.add_argument("--state", required=True)
    submit.add_argument("--request", required=True)
    submit.add_argument("--request-id", required=True)
    submit.add_argument("--call-id", required=True)
    batch_sheet = sub.add_parser(
        "batch-sheet", help="Print a staff-readable request; does not send it"
    )
    batch_sheet.add_argument("--state", required=True)
    batch_sheet.add_argument("--request-id", required=True)
    accept = sub.add_parser("accept", help="Owner records operator review, not facility admission")
    accept.add_argument("--state", required=True)
    accept.add_argument("--request-id", required=True)
    accept.add_argument("--operator", required=True)
    accept.add_argument("--decision", choices=("accept", "deviate", "reject"), default="accept")
    accept.add_argument("--notes", default="")
    accept.add_argument("--deviations", help="JSON describing departure from original request")
    accept.add_argument("--call-id")
    receive = sub.add_parser("receive", help="Owner imports originals; evidence remains unreleased")
    receive.add_argument("--state", required=True)
    receive.add_argument("--request-id", required=True)
    receive.add_argument("--delivery", required=True)
    receive.add_argument(
        "--files", required=True, help="JSON map of logical filename to source path"
    )
    receive.add_argument("--call-id")
    release = sub.add_parser("release", help="Owner releases a reviewed delivery to investigator")
    release.add_argument("--state", required=True)
    release.add_argument("--delivery-id", required=True)
    release.add_argument("--reviewer", required=True)
    release.add_argument("--call-id")
    measure = sub.add_parser(
        "measure", help="Reduce raw measurements; grants no provenance authority"
    )
    reduction = measure.add_subparsers(dest="method", required=True)
    sps = reduction.add_parser("sps-log")
    sps.add_argument("path")
    density = reduction.add_parser("density")
    density.add_argument(
        "--record", required=True, help="JSON keyword inputs for Archimedes reduction"
    )
    microscopy = reduction.add_parser("microscopy")
    microscopy.add_argument("--record", required=True)
    microscopy.add_argument("--source-file", required=True)
    specimen = reduction.add_parser("microscopy-specimen",
        help="Aggregate identified measured fields; does not create independent specimens")
    specimen.add_argument("--record", required=True,
        help="JSON object with records and coarse_threshold_nm")
    review = reduction.add_parser("review",
        help="Record explicit operator quality review; does not release evidence")
    review.add_argument("--record", required=True,
        help="JSON object with observation, decision, reviewer and rationale")
    score = sub.add_parser("evaluate", help="Compare immutable forecasts against released outcomes")
    score.add_argument("--state", required=True)
    score.add_argument("--request-id", required=True)
    return root


def batch_text(record):
    request = record["request"]
    lines = [
        f"# Batch request {record['request_id']}",
        "",
        f"Evidence origin requested: {request['origin']}",
        f"Lot: {request['lot_id']}",
        f"Request digest: {record['request_sha256']}",
        f"Prospective record: {record['prospective_ref']['sha256']}",
        f"Model: {record['model_id']}",
        f"Committed: {record['committed_at']}",
        "",
        "This document requests review. It is not facility approval or a machine command.",
        "",
        "## Specimens and requested conditions",
        "",
    ]
    for specimen in request["specimens"]:
        lines.extend(
            [
                f"### {specimen['specimen_id']}",
                "",
                f"Preparation: {specimen['preparation_id']}; cycle: {specimen['cycle_id']}",
                "```json",
                json.dumps(specimen["conditions"], indent=2),
                "```",
                "",
            ]
        )
    lines.extend(
        [
            "## Predictions committed before execution",
            "",
            "```json",
            json.dumps(record["prediction"], indent=2),
            "```",
            "",
            "Return original logs and measurements with actual settings, sample identities,",
            "methods, calibrations and deviations. Unknown delivered values stay unknown.",
            "Record operator review before execution. Return partial deliveries explicitly.",
        ]
    )
    return "\n".join(lines)


def dispatch(args):
    if args.command == "measure":
        if args.method == "sps-log":
            return read_sps_csv(args.path)
        if args.method == "density":
            return density_archimedes(**read_json(args.record))
        if args.method == "microscopy-specimen":
            return microscopy_specimen_observations(**read_json(args.record))
        if args.method == "review":
            return review_reduction(**read_json(args.record))
        return microscopy_observations(read_json(args.record), source_file=args.source_file)
    state = Path(args.state).expanduser().resolve()
    if args.command == "init-simulation":
        from .workflow import initialize_simulation

        return initialize_simulation(
            state,
            Path(args.run_dir) / "scientific_state",
            campaign_id=args.campaign_id,
            max_specimens=args.max_specimens,
            microstructure=args.microstructure,
        )
    if args.command == "init":
        config = read_json(args.config) if args.config else {}
        config.update(campaign_id=args.campaign_id, execution_mode=args.mode)
        with Campaign.open(state, config) as campaign:
            return campaign.state()
    if not (state / "campaign.sqlite3").is_file():
        raise ValueError("existing campaign state required; use init explicitly")
    if args.command == "fulfill-simulation":
        from .workflow import fulfill_simulation

        return fulfill_simulation(
            state,
            args.request_id,
            runtime=args.runtime,
            artifact_directory=args.artifacts,
            world_config=read_json(args.world_config),
            seed=args.seed,
        )
    with Campaign.open(state) as campaign:
        if args.command in {"status", "verify", "evidence", "artifacts"}:
            method = "state" if args.command == "status" else args.command
            return getattr(campaign, method)()
        if args.command in {"adopt", "submit"}:
            from .investigation.controller import Investigator

            investigator = Investigator(campaign, state / "investigator")
            try:
                if args.command == "adopt":
                    staged = investigator.call(
                        args.call_id + ":stage",
                        "stage_model",
                        {"source": Path(args.source).read_text()},
                    )
                    return investigator.call(
                        args.call_id,
                        "adopt_model",
                        {
                            "source_sha256": staged["source_sha256"],
                            "rationale": args.rationale,
                            "test_request": read_json(args.test_request),
                        },
                    )
                return investigator.call(
                    args.call_id,
                    "submit_batch",
                    {"request_id": args.request_id, "request": read_json(args.request)},
                )
            finally:
                investigator.close()
        if args.command == "batch-sheet":
            return batch_text(campaign.request(args.request_id))
        if args.command == "accept":
            return campaign.accept(
                args.request_id,
                args.operator,
                args.notes,
                decision=args.decision,
                deviations=read_json(args.deviations) if args.deviations else None,
                call_id=args.call_id,
            )
        if args.command == "receive":
            return campaign.receive(
                args.request_id,
                read_json(args.delivery),
                {k: Path(v) for k, v in read_json(args.files).items()},
                call_id=args.call_id,
            )
        if args.command == "release":
            return campaign.release(args.delivery_id, args.reviewer, call_id=args.call_id)
        if args.command == "evaluate":
            record = campaign.request(args.request_id)
            observations = [e for e in campaign.evidence() if e["request_id"] == args.request_id]
            return {
                "request_id": args.request_id,
                "prospective_ref": record["prospective_ref"],
                **evaluate_campaign_request(record, observations),
            }
    raise ValueError("unsupported command")


def main(argv=None):
    args = parser().parse_args(argv)
    try:
        result = dispatch(args)
    except (ValueError, TypeError, OSError, KeyError) as exc:
        print(
            json.dumps({"status": "error", "error_type": type(exc).__name__, "error": str(exc)}),
            file=sys.stderr,
        )
        return 1
    print(result if isinstance(result, str) else json.dumps(result, indent=2, allow_nan=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
